mapper.select:
select party_no, party_title, party_status, target_qty, split_datetime, product_name
from party
where user_no = #{userNo}

mapper.insert:
insert into party(PARTY_TITLE, TARGET_QTY, SPLIT_DATETIME, SPLIT_ADDR
			  ,SPLIT_PLACE, LONGITUDE, LATITUDE, PRODUCT_NAME
			  , PRODUCT_CONTENT,PRODUCT_PRICE, PRODUCT_IMG
			  , PARTY_ENDDATETIME, ACCUM_QTY, PARTY_STATUS
			  , PARTY_DATETIME, RECENT_UPDATE, MAX_QTY, USER_NO
			  , REGION_NO, USER_NAME) 
values (#{partyTitle}, #{targetQty}, #{splitDatetime}, #{splitAddr}
			  , #{splitPlace}, #{longitude}, #{latitude}
			  , #{productName}, #{productContent}
			  , #{productPrice}, #{productImg}, #{partyEndDateTime}
			  , #{accumQty}, '모집 중', #{partyDateTime}, #{recentUpdate}
			  , #{maxQty}, #{userNo}, #{regionNo}, #{userName})

mapper.update:
update party
set accum_qty = accum_qty + #{qty}
where party_no = #{partyNo}
